import{z as n,x as d,o as r,c as B,q as s,j as l,D as A,d as e,s as i,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"RPC 语义","description":"","frontmatter":{"title":"RPC 语义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rpc-semantics.md","filePath":"cs/rpc-semantics.md","lastUpdated":1791063341000}'),p={name:"cs/rpc-semantics.md"};function C(c,a,D,m,P,f){const t=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=s('<h1 id="rpc-语义" tabindex="-1">RPC 语义 <a class="header-anchor" href="#rpc-语义" aria-label="Permalink to &quot;RPC 语义&quot;">​</a></h1><div class="epigraph"><p>远程调用看起来像本地过程，失败模式不像。至少一次、至多一次、恰好一次是对「过程执行了几次」的承诺，不是营销。</p><footer>—— 据 Birrell and Nelson, Implementing Remote Procedure Calls, TOCS 1984；Spector, Performing Remote Operations Efficiently, CACM 1982 整理</footer></div><p>共识单元以<a href="/cs/pow-blockchain-consensus">PoW 直觉</a>封口。系统模式课序从通信开始。缺口不是再选主，而是<strong>一次调用在故障下执行了几遍</strong>。本课钉 RPC 的执行语义。后课投递语义把消息层的至少/至多说清，二者常被混名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Birrell–Nelson：桩、报文、绑定、超时。本地调用：进程活则恰好执行一次。RPC：请求丢、应答丢、服务器崩在执行前/中/后，客户端超时后看见的都是「没回来」。缺口：重试会把「执行前崩」变成成功，也会把「执行后应答丢」变成执行两遍。</p><p>Spector 把远程操作分成至少一次、至多一次等。至少一次：重试直到一次成功应答，执行次数 \\(\\ge 1\\)（若终成功）。至多一次：执行次数 \\(\\le 1\\)，可能零次（超时后不知道）。恰好一次：又回到共识与幂等的税。</p><p><span class="marginnote">「at-most-once」常靠服务器端调用 ID 表实现，表要有过期，过期后又滑回至少一次。本课先定词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接口必须声明语义。默认最常见的工程是：超时重试 + 希望处理函数幂等 ≈ 试图至少一次。真至多一次：服务器记住 <code>(client, xid)</code> 的结果。真恰好一次：把调用当 RSM 命令或用事务。</p>',9)),(r(),l(o,null,{default:A(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22RPC%22%5D%20--%3E%20TO%5B%22%E8%B6%85%E6%97%B6%22%5D%0A%20%20TO%20--%3E%20RET%5B%22%E9%87%8D%E8%AF%95%22%5D%0A%20%20RET%20--%3E%20DUP%5B%22%E5%8F%AF%E8%83%BD%E4%BA%8C%E6%AC%A1%E6%89%A7%E8%A1%8C%22%5D%0A%20%20DUP%20--%3E%20IDEM%5B%22%E8%A6%81%E5%B9%82%E7%AD%89%20%E5%90%8E%E8%AF%BE%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("不要把 TCP 「恰好一次字节流」当成恰好一次过程：流保证段，不保证应用执行与应答的原子。"),E("span",{class:"marginnote"},"常见误区：初学者容易以为「TCP 可靠，所以远程调用不会重复」——TCP 保证的只是这条连接内的字节到达且不重不漏；连接一断、超时一到，应用层照样要重试，重试的对象是「过程」而不是「字节」。字节没丢，不代表服务器没把同一个过程跑两遍。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("崩溃恢复：服务器若在执行后、记 xid 前崩，至多一次表会漏，重试再执行。xid 必须与副作用同事务落盘——又接到 WAL。无状态服务器最容易做成至少一次。"),E("span",{class:"marginnote"},"术语翻译：xid 表就是用「客户端给每次调用发一张唯一票据、服务器把票据连同结果记进本子」的手段来做「同一张票据再来时不重跑、直接把本子上的旧结果念回去」的事。本子没落盘就崩，票据等于没验过——这正是下面那张图里最危险的崩溃点。")],-1)),(r(),l(o,null,{default:A(()=>[i(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%8F%91%E5%87%BA%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20CRASH%7B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%9C%A8%E5%93%AA%E4%B8%80%E6%AD%A5%E5%B4%A9%EF%BC%9F%22%7D%0A%20%20CRASH%20--%20%22%E6%89%A7%E8%A1%8C%E5%89%8D%22%20--%3E%20P1%5B%22%E6%9C%AA%E6%89%A7%E8%A1%8C%EF%BC%9A%E9%87%8D%E8%AF%95%E5%AE%89%E5%85%A8%22%5D%0A%20%20CRASH%20--%20%22%E6%89%A7%E8%A1%8C%E4%B8%AD%22%20--%3E%20P2%5B%22%E5%89%AF%E4%BD%9C%E7%94%A8%E6%9C%AA%E7%9F%A5%EF%BC%9A%E9%87%8D%E8%AF%95%E5%8F%AF%E8%83%BD%E9%87%8D%E5%A4%8D%22%5D%0A%20%20CRASH%20--%20%22%E6%89%A7%E8%A1%8C%E5%90%8E%E3%80%81%E8%AE%B0%20xid%20%E5%89%8D%22%20--%3E%20P3%5B%22%E5%B7%B2%E6%89%A7%E8%A1%8C%E4%BD%86%E8%A1%A8%E6%9C%AA%E8%AE%B0%EF%BC%9A%E9%87%8D%E8%AF%95%E5%BF%85%E7%84%B6%E9%87%8D%E5%A4%8D%22%5D%0A%20%20CRASH%20--%20%22%E6%89%A7%E8%A1%8C%E5%90%8E%E4%B8%94%20xid%20%E5%B7%B2%E8%90%BD%E7%9B%98%22%20--%3E%20P4%5B%22%E9%87%8D%E8%AF%95%E5%91%BD%E4%B8%AD%E8%A1%A8%EF%BC%9A%E8%BF%94%E5%9B%9E%E7%BC%93%E5%AD%98%E7%BB%93%E6%9E%9C%22%5D%0A%20%20P4%20--%3E%20SAFE%5B%22%E6%95%88%E6%9E%9C%E4%B8%8A%E6%81%B0%E5%A5%BD%E4%B8%80%E6%AC%A1%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>绑定与版本：桩与服务器 stub 不一致是另一类失败，不是执行次数。本课点名。部分同步下超时只是<a href="/cs/failure-detectors">检测器</a>，不能当「对方没执行」的证明——这是 FLP 在 RPC 上的投影。</p><p>本课不写 gRPC 流式 API 全文，不写限价簿下单 RPC。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把消息队列的投递保证写完（下一课）。不引入 Saga。后课默认：说到 RPC，先问三次语义；超时后的知识状态是「不知道」，除非服务器给了持久 xid 结果。幂等键是把至少一次压成效果一次。<span class="marginnote">数字实例：客户端向支付服务扣款 100 元，超时后重发了 3 次同一请求。至少一次语义下服务器可能老老实实扣 3 次、共 300 元；若把「扣款单号」当幂等键，服务器看到 3 张相同单号只执行 1 次——3 次投递被压成 1 次扣款，这就是「投递多次、效果一次」。</span></p><p>本地过程的等式在远程不成立。失败是常态规格，不是异常注释。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>至少一次、至多一次、恰好一次谈的是执行次数。</li><li>超时后客户端不知道；重试提高执行次数。</li><li>TCP 字节可靠 ≠ 过程恰好一次。</li><li>出处：Birrell and Nelson, TOCS 1984；Spector, 1982。</li></ul>',7))])}const T=n(p,[["render",C]]);export{u as __pageData,T as default};
